),
events AS (
    SELECT
        t.user_id,
        u.user_name,
        u.control_user_group,
        t.strategy_name,
        t.ip,
        t.bullet_level,
        t.fish_value,
        t.multiplier
    FROM public.bullet AS t
    INNER JOIN user_map AS u ON t.user_id = u.user_id
    WHERE t.op_code NOT IN ('B26', 'TST', 'TSB', 'TSO')
      AND t.currency_type IN ('CNY')
      AND t.event_timestamp > '2025-01-01'
)
SELECT
    user_id,
    user_name,
    control_user_group,
    'bullet_level' AS metric,
    CAST(CAST(TRUNC(bullet_level) AS BIGINT) AS VARCHAR) AS category,
    COUNT(*) AS n
FROM events
WHERE bullet_level IS NOT NULL
GROUP BY 1, 2, 3, 5

UNION ALL

SELECT
    user_id,
    user_name,
    control_user_group,
    'strategy_name' AS metric,
    NVL(strategy_name, 'UNKNOWN') AS category,
    COUNT(*) AS n
FROM events
GROUP BY 1, 2, 3, 5

UNION ALL

SELECT
    user_id,
    user_name,
    control_user_group,
    'ip' AS metric,
    NVL(ip, 'UNKNOWN') AS category,
    COUNT(*) AS n
FROM events
GROUP BY 1, 2, 3, 5

UNION ALL

SELECT
    user_id,
    user_name,
    control_user_group,
    'fish_value' AS metric,
    CAST(CAST(TRUNC(fish_value) AS BIGINT) AS VARCHAR) AS category,
    COUNT(*) AS n
FROM events
WHERE fish_value IS NOT NULL
GROUP BY 1, 2, 3, 5

UNION ALL

SELECT
    user_id,
    user_name,
    control_user_group,
    'multiplier_x_bullet' AS metric,
    CASE WHEN multiplier = TRUNC(multiplier) THEN CAST(CAST(multiplier AS BIGINT) AS VARCHAR) || '.0' ELSE CAST(multiplier AS VARCHAR) END || 'x_L' || CAST(CAST(TRUNC(bullet_level) AS BIGINT) AS VARCHAR) AS category,
    COUNT(*) AS n
FROM events
WHERE multiplier IS NOT NULL AND bullet_level IS NOT NULL
GROUP BY 1, 2, 3, 5
